<?php
require_once dirname(__DIR__) . '/config/config.php'; require_once ROOT_PATH . '/includes/functions.php'; require_once __DIR__.'/_layout.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: 0; $product=null; $images=[]; $error=null;
try { $product=(new Product())->findById($id); if($product){ try{$stmt=Database::getInstance()->getConnection()->prepare('SELECT image FROM product_images WHERE product_id = ? ORDER BY is_primary DESC, sort_order');$stmt->execute([$id]);$images=$stmt->fetchAll();}catch(PDOException $ignored){ } } } catch(PDOException $exception){error_log('Product details unavailable: '.$exception->getMessage());$error='Product details are temporarily unavailable.';}
if(!$product){http_response_code(404);shopHeader('Product not found');?><main class="container shop-main"><div class="shop-empty"><h1><?= e($error ?: 'Product not found') ?></h1><a class="button-outline" href="<?= e(BASE_URL) ?>/shop/products.php">Return to marketplace</a></div></main><?php shopFooter(); exit;}
$image=(string)($product['image']??''); shopHeader($product['name']); ?>
<main class="container shop-main"><div class="shop-breadcrumb"><a href="<?= e(BASE_URL) ?>/shop/products.php">Marketplace</a> / <?= e($product['category_name']??'Product') ?> / <?= e($product['name']) ?></div><div class="detail-layout"><div class="detail-image"><?php if($image): ?><img src="<?= e($image) ?>" alt="<?= e($product['name']) ?>"><?php else: ?><span><?= e(strtoupper(substr($product['name'],0,1))) ?></span><?php endif; ?></div><div class="detail-info"><small><?= e($product['category_name']??'General merchandise') ?></small><h1><?= e($product['name']) ?></h1><p class="description"><?= e($product['description'] ?: 'Quality merchandise from a trusted Quincy Store supplier.') ?></p><div class="detail-price"><small>Wholesale price</small><strong><?= e(formatPrice($product['wholesale_price'] ?? $product['retail_price'] ?? 0)) ?></strong><span>per <?= e($product['unit']??'unit') ?></span></div><div class="detail-meta"><div>Minimum order quantity<b><?= (int)($product['minimum_order_quantity']??1) ?> <?= e($product['unit']??'units') ?></b></div><div>Availability<b><?= (int)($product['available_quantity']??0) ?> in stock</b></div><div>SKU<b><?= e($product['sku']??'Available on request') ?></b></div><div>Category<b><?= e($product['category_name']??'General') ?></b></div></div><div class="detail-actions"><a class="button button-primary" href="<?= e(BASE_URL) ?>/b2b/request-quotation.php?product=<?= (int)$product['id'] ?>">Request a quote</a><a class="button-outline" href="<?= e(BASE_URL) ?>/shop/suppliers.php">Find supplier</a></div></div></div></main>
<?php shopFooter(); ?>
